CREATE TABLE IF NOT EXISTS asset_onboarding_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_code text NOT NULL UNIQUE, asset_id uuid REFERENCES continental_assets(id) ON DELETE SET NULL, submitted_by_reference text, asset_name text NOT NULL, asset_type text NOT NULL, country_code text, jurisdiction_reference text, locality text, geographic_reference text, submission_purpose text, workflow_status text NOT NULL DEFAULT 'Submitted', current_gate text NOT NULL DEFAULT 'Identity & Intake', risk_level text NOT NULL DEFAULT 'Unrated', passport_status text NOT NULL DEFAULT 'Not Issued', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset_onboarding_parties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE CASCADE, party_type text NOT NULL, party_reference text NOT NULL, role_description text, identity_status text NOT NULL DEFAULT 'Unverified', beneficial_ownership_status text NOT NULL DEFAULT 'Unverified', evidence_reference text, verification_notes text, status text NOT NULL DEFAULT 'Pending');
CREATE TABLE IF NOT EXISTS asset_onboarding_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE CASCADE, document_type text NOT NULL, document_reference text NOT NULL, issuer text, issue_date date, expiry_date date, document_hash text, authenticity_status text NOT NULL DEFAULT 'Unverified', completeness_status text NOT NULL DEFAULT 'Unreviewed', extracted_data jsonb NOT NULL DEFAULT '{}'::jsonb, evidence_status text NOT NULL DEFAULT 'Pending', reviewer_reference text, reviewed_at timestamptz, notes text, status text NOT NULL DEFAULT 'Submitted');
CREATE TABLE IF NOT EXISTS asset_onboarding_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE CASCADE, check_type text NOT NULL, target_reference text, result text NOT NULL DEFAULT 'Pending', risk_level text NOT NULL DEFAULT 'Unrated', findings text, source_reference text, reviewer_reference text, checked_at timestamptz, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS asset_onboarding_gates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE CASCADE, gate_code text NOT NULL, gate_name text NOT NULL, sequence_no integer NOT NULL, decision text NOT NULL DEFAULT 'Pending', blocking_reason text, reviewer_reference text, evidence_reference text, decided_at timestamptz, status text NOT NULL DEFAULT 'Open', UNIQUE(case_id,gate_code));
CREATE TABLE IF NOT EXISTS asset_onboarding_risks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE CASCADE, risk_category text NOT NULL, severity text NOT NULL DEFAULT 'Medium', likelihood text NOT NULL DEFAULT 'Possible', score numeric(8,2), description text NOT NULL, mitigation text, residual_risk text, source_reference text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS asset_passports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES asset_onboarding_cases(id) ON DELETE CASCADE UNIQUE, asset_id uuid REFERENCES continental_assets(id) ON DELETE SET NULL, passport_number text NOT NULL UNIQUE, passport_version text NOT NULL DEFAULT '1.0', issuance_status text NOT NULL DEFAULT 'Draft', integrity_status text NOT NULL DEFAULT 'Unverified', ownership_summary text, title_summary text, rights_summary text, environmental_summary text, encumbrance_summary text, valuation_summary text, diligence_summary text, investment_summary text, risk_summary text, evidence_count integer NOT NULL DEFAULT 0, verified_evidence_count integer NOT NULL DEFAULT 0, issued_at timestamptz, issued_by_reference text, hash_reference text, expiry_date date, status text NOT NULL DEFAULT 'Draft');
CREATE INDEX IF NOT EXISTS idx_onboarding_status ON asset_onboarding_cases(workflow_status,current_gate);
CREATE INDEX IF NOT EXISTS idx_onboarding_docs_case ON asset_onboarding_documents(case_id);
CREATE INDEX IF NOT EXISTS idx_onboarding_checks_case ON asset_onboarding_checks(case_id);